<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const props=defineProps({constraints:Boolean}),data=ref(null),title=ref(''),preferences=ref(''),allowed=ref(false),ack=ref(false),error=ref(''),notice=ref(''),writes=useWorkflowWrite('phase')
async function load(){try{data.value=await api.flow('/phase');title.value=data.value.phase?.payload.title||'';preferences.value=data.value.phase?.payload.preferences||'';allowed.value=!!data.value.phase?.payload.ai_allowed}catch(e){error.value=e.message}}
async function save(){try{const old=data.value.phase?.payload||{};await writes.send('/phase',{expected_version:data.value.phase?.version||0,title:title.value,preferences:preferences.value,ai_allowed:allowed.value,goal:old.goal||'',deadline:old.deadline||null},'PUT');await load();notice.value='阶段背景已保存。'}catch(e){error.value=e.message}}
async function constraint(action){try{await writes.send('/phase/'+action,{expected_version:data.value.phase.version,...(action==='accept-constraint'?{acknowledge:ack.value}:{})});await load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="card"><h2>{{ constraints?'娱乐约定':'当前阶段 · 可选' }}</h2><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><template v-if="constraints"><p>默认温和提醒；严格与加强须在开始前同意，只影响之后的新会话。</p><p>当前阶段：{{ data?.phase?.payload.title||'未设置' }} <RouterLink to="/plans">到计划更新阶段与主线 →</RouterLink></p><button class="btn" :disabled="writes.busy.value||!data?.phase?.payload.ai_allowed" @click="constraint('analyze')">{{ writes.busy.value?'正在分析约定…':'请本人模型建议未来约定' }}</button><p v-if="!data?.phase?.payload.ai_allowed" class="muted">先在计划中保存并授权阶段背景，仍可直接使用温和计时。</p><template v-if="data?.phase?.pending"><p>{{ data.phase.pending.reason }} · {{ {gentle:'温和提醒',strong:'加强提醒',strict:'严格'}[data.phase.pending.mode]||data.phase.pending.mode }}</p><label><input type="checkbox" v-model="ack"/>我明确同意此约定，仅用于未来开始的会话</label><button class="btn" :disabled="writes.busy.value||!ack" @click="constraint('accept-constraint')">接受未来约定</button></template></template><form v-else @submit.prevent="save"><div class="form-grid"><label>阶段名称<input v-model="title" maxlength="120" placeholder="例如：平常日常 / 准备考试 / 休息调整"/></label><label>当前精力与安排（可空）<input v-model="preferences" maxlength="4000"/></label></div><label><input type="checkbox" v-model="allowed"/>允许作为之后主动分析的背景</label><button class="btn" :disabled="writes.busy.value">保存阶段</button><details v-if="data?.phase?.payload.goal||data?.phase?.payload.deadline"><summary>原阶段资料（历史保留）</summary><p>{{ data.phase.payload.goal }} · {{ data.phase.payload.deadline }}</p><p class="muted">如仍适用，请在目标中明确维护，不按同名自动合并。</p></details></form></section></template>
